export type SketchScene = {
  viewBox: string;
  /** Static pencil layers, far to near, served from /public/hero. */
  layers: { src: string; delay: number }[];
  /** Red ink network, inline so its CSS draw-in runs (and respects reduced motion). */
  network: string;
};

/**
 * Hand-drawn hero scene generated by scripts/hero/*.mjs. The pencil layers are
 * cached SVG files (kept out of the HTML); only the red network is inline.
 * object-cover + right-bottom matches the network's xMaxYMax slice.
 */
export function SketchSceneView({ scene, className }: { scene: SketchScene; className: string }) {
  return (
    <div aria-hidden className={className}>
      <div className="hero-frame">
      {scene.layers.map(({ src, delay }) => (
        // eslint-disable-next-line @next/next/no-img-element -- decorative static SVG, no optimisation needed
        <img
          key={src}
          src={src}
          alt=""
          decoding="async"
          className="hero-layer absolute inset-0 h-full w-full object-cover object-right-bottom"
          style={delay ? { animationDelay: `${delay}ms` } : undefined}
        />
      ))}
      <svg
        viewBox={scene.viewBox}
        preserveAspectRatio="xMaxYMax slice"
        fill="none"
        strokeLinecap="round"
        strokeLinejoin="round"
        className="absolute inset-0 h-full w-full"
        dangerouslySetInnerHTML={{ __html: scene.network }}
      />
      </div>
    </div>
  );
}
